mapper.select:
SELECT id, user_id, scope_type, character_id, member_id, voice_id, created_at, updated_at
FROM app_user_tts_voice_binding
WHERE user_id = #{userId} AND scope_type = #{scopeType}
  AND character_id = #{characterId} AND member_id = #{memberId}
LIMIT 1

mapper.update:
UPDATE app_user_tts_voice_binding
SET voice_id = #{voiceId}, updated_at = CURRENT_TIMESTAMP
WHERE user_id = #{userId} AND scope_type = #{scopeType}
  AND character_id = #{characterId} AND member_id = #{memberId}

mapper.delete:
DELETE FROM app_user_tts_voice_binding
WHERE user_id = #{userId} AND scope_type = #{scopeType}
  AND character_id = #{characterId} AND member_id = #{memberId}

DELETE FROM app_user_tts_voice_binding
WHERE user_id = #{userId} AND scope_type = 'MEMBER'
  AND character_id = #{characterId} AND member_id = #{memberId}

DELETE FROM app_user_tts_voice_binding
WHERE user_id = #{userId} AND scope_type = 'MEMBER'
  AND character_id = #{characterId}

DELETE FROM app_user_tts_voice_binding
WHERE user_id = #{userId} AND character_id = #{characterId}
  AND scope_type IN ('CHARACTER', 'MEMBER')
